using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace PhotoTutor {
 internal sealed class QuestionPage {
  internal string Id=Guid.NewGuid().ToString("N"),File="",Label="";internal int Width,Height,Revision,Orientation;
  internal BitmapSource Decode(){using(var stream=System.IO.File.OpenRead(File)){var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=stream;image.EndInit();image.Freeze();return image;}}
 }
 internal sealed class QuestionRegion {
  internal string Id=Guid.NewGuid().ToString("N"),PageId="",Role="unknown";internal int PageRevision;internal Int32Rect Bounds;internal bool Candidate;internal double Confidence;
 }
 internal sealed class QuestionGroup {
  internal string Id=Guid.NewGuid().ToString("N"),Name="本题";internal readonly List<string> Regions=new List<string>();
 }
 internal sealed class QuestionPayload {
  internal string GroupId="",GroupName="",Instruction="";internal int RegionCount,SourcePageCount;internal long Revision;internal PhotoData[] Images=Array.Empty<PhotoData>();
 }
 // Source pages are encoded on disk. Only the visible source and selected composites are decoded.
 internal sealed class QuestionWorkspace:IDisposable {
  internal readonly List<QuestionPage> Pages=new List<QuestionPage>();internal readonly List<QuestionRegion> Regions=new List<QuestionRegion>();internal readonly List<QuestionGroup> Groups=new List<QuestionGroup>();
  internal long Revision {get;private set;}internal string ActiveId="";readonly string folder;bool disposed;
  internal QuestionWorkspace(string cacheRoot){folder=Path.Combine(cacheRoot,"regions_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"owned.cache"),"QuestionWorkspace v1");NewGroup();}
  internal QuestionGroup Active=>Groups.Single(g=>g.Id==ActiveId);
  internal QuestionWorkspace Clone(){if(disposed)throw new ObjectDisposedException(nameof(QuestionWorkspace));var copy=new QuestionWorkspace(Path.GetDirectoryName(folder)!);try{copy.Groups.Clear();foreach(var page in Pages){var next=new QuestionPage{Id=page.Id,Label=page.Label,Width=page.Width,Height=page.Height,Revision=page.Revision,Orientation=page.Orientation};next.File=Path.Combine(copy.folder,page.Id+".png");System.IO.File.Copy(page.File,next.File);copy.Pages.Add(next);}foreach(var region in Regions)copy.Regions.Add(new QuestionRegion{Id=region.Id,PageId=region.PageId,Role=region.Role,PageRevision=region.PageRevision,Bounds=region.Bounds,Candidate=region.Candidate,Confidence=region.Confidence});foreach(var group in Groups){var next=new QuestionGroup{Id=group.Id,Name=group.Name};next.Regions.AddRange(group.Regions);copy.Groups.Add(next);}copy.ActiveId=ActiveId;copy.Revision=Revision;return copy;}catch{copy.Dispose();throw;}}
  internal QuestionGroup NewGroup(){var g=new QuestionGroup{Name="题目"+(Groups.Count+1)};Groups.Add(g);ActiveId=g.Id;Revision++;return g;}
  internal void Select(string id){if(Groups.All(g=>g.Id!=id))throw new InvalidOperationException("题目已失效。");ActiveId=id;Revision++;}
  internal QuestionPage AddFile(string file){var original=PhotoData.FromFileForSelection(file);return Add(original.Image,Path.GetFileName(file));}
  internal QuestionPage Add(BitmapSource image,string label){if(Pages.Count>=6)throw new InvalidOperationException("最多6个原始页面，请开始新对话或删除无关页面。");if((long)image.PixelWidth*image.PixelHeight>24000000||image.PixelWidth<32||image.PixelHeight<32)throw new InvalidOperationException("原始页面尺寸不合适。");var page=new QuestionPage{Width=image.PixelWidth,Height=image.PixelHeight,Label=label};page.File=Path.Combine(folder,page.Id+".png");Write(image,page.File);Pages.Add(page);Revision++;return page;}
  static void Write(BitmapSource image,string file){var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var stream=System.IO.File.Create(file))encoder.Save(stream);}
  internal void CopyOriginal(PhotoData original){if(original.OriginalFile==null){Add(original.Image,original.Label);return;}if(Pages.Count>=6)throw new InvalidOperationException("最多6个原始页面。");var page=new QuestionPage{Width=original.OriginalWidth,Height=original.OriginalHeight,Label=original.Label};page.File=Path.Combine(folder,page.Id+".png");System.IO.File.Copy(original.OriginalFile,page.File);Pages.Add(page);Revision++;}
  internal QuestionRegion AddRegion(string pageId,Int32Rect rect,bool candidate=false,double confidence=1){var p=Pages.Single(x=>x.Id==pageId);if(rect.Width<32||rect.Height<32||rect.X<0||rect.Y<0||rect.X+rect.Width>p.Width||rect.Y+rect.Height>p.Height)throw new InvalidOperationException("选区太小或超出原图。");if(Regions.Count>=80)throw new InvalidOperationException("选区过多，请删除无关选区。");var r=new QuestionRegion{PageId=p.Id,PageRevision=p.Revision,Bounds=rect,Candidate=candidate,Confidence=confidence};Regions.Add(r);Revision++;return r;}
  internal void Attach(string regionId,bool independent=false){var r=Regions.Single(x=>x.Id==regionId);Validate(r);if(independent&&Active.Regions.Count>0)NewGroup();if(Active.Regions.Contains(regionId))return;if(Active.Regions.Count>=12)throw new InvalidOperationException("一道题最多12个区域，请合并相邻且属于同题的区域。");Active.Regions.Add(regionId);r.Candidate=false;Revision++;}
  internal void SetRole(string regionId,string role){if(!new[]{"unknown","stem","question","figure","options"}.Contains(role))throw new InvalidOperationException("区域角色无效。");Regions.Single(x=>x.Id==regionId).Role=role;Revision++;}
  internal void Detach(string regionId){if(!Active.Regions.Remove(regionId))return;if(!Groups.Any(g=>g.Regions.Contains(regionId)))Regions.RemoveAll(r=>r.Id==regionId);Revision++;}
  internal void Move(string regionId,int direction){int index=Active.Regions.IndexOf(regionId),next=index+direction;if(index<0||next<0||next>=Active.Regions.Count)return;Active.Regions.RemoveAt(index);Active.Regions.Insert(next,regionId);Revision++;}
  internal void Replace(string regionId,Int32Rect bounds){var r=Regions.Single(x=>x.Id==regionId);var p=Pages.Single(x=>x.Id==r.PageId);if(bounds.Width<32||bounds.Height<32||bounds.X<0||bounds.Y<0||bounds.X+bounds.Width>p.Width||bounds.Y+bounds.Height>p.Height)throw new InvalidOperationException("重新框选超出原图。");r.Bounds=bounds;r.PageRevision=p.Revision;Revision++;}
  internal void Rotate(string pageId){var p=Pages.Single(x=>x.Id==pageId);var rotated=new TransformedBitmap(p.Decode(),new RotateTransform(90));rotated.Freeze();string next=p.File+".new";Write(rotated,next);System.IO.File.Copy(next,p.File,true);System.IO.File.Delete(next);p.Width=rotated.PixelWidth;p.Height=rotated.PixelHeight;p.Orientation=(p.Orientation+90)%360;p.Revision++;var ids=Regions.Where(r=>r.PageId==pageId).Select(r=>r.Id).ToArray();foreach(var g in Groups)g.Regions.RemoveAll(ids.Contains);Regions.RemoveAll(r=>r.PageId==pageId);Revision++;}
  internal void RemovePage(string pageId){var ids=Regions.Where(r=>r.PageId==pageId).Select(r=>r.Id).ToArray();foreach(var g in Groups)g.Regions.RemoveAll(ids.Contains);Regions.RemoveAll(r=>r.PageId==pageId);var p=Pages.Single(x=>x.Id==pageId);Pages.Remove(p);System.IO.File.Delete(p.File);Revision++;}
  internal void RemoveCandidates(string pageId){Regions.RemoveAll(r=>r.Candidate&&r.PageId==pageId);Revision++;}
  internal bool AcceptCandidates(string pageId,int pageRevision,long stamp,IEnumerable<RegionCandidate> candidates){var p=Pages.SingleOrDefault(x=>x.Id==pageId);if(disposed||p==null||p.Revision!=pageRevision||Revision!=stamp)return false;var pending=candidates.ToArray();if(Regions.Count(r=>!r.Candidate||r.PageId!=pageId)+pending.Length>80)throw new InvalidOperationException("选区过多，请删除无关区域后再分析。");foreach(var r in pending)if(r.Bounds.Width<32||r.Bounds.Height<32||r.Bounds.X<0||r.Bounds.Y<0||r.Bounds.X+r.Bounds.Width>p.Width||r.Bounds.Y+r.Bounds.Height>p.Height)throw new InvalidOperationException("候选边界无效，已保留现有手动选区。");RemoveCandidates(pageId);foreach(var r in pending)AddRegion(pageId,r.Bounds,true,r.Confidence);return true;}
  void Validate(QuestionRegion r){var p=Pages.SingleOrDefault(x=>x.Id==r.PageId);if(p==null||p.Revision!=r.PageRevision)throw new InvalidOperationException("原图已旋转或更换，旧区域需要重新框选。");}
  internal QuestionPayload Compose(bool high,CancellationToken token){if(disposed)throw new ObjectDisposedException(nameof(QuestionWorkspace));long stamp=Revision;string groupId=ActiveId;var ids=Active.Regions.ToArray();if(ids.Length==0)throw new InvalidOperationException("请先添加选区到本题，或点选已分组的题目。");var selected=ids.Select(id=>Regions.Single(x=>x.Id==id)).ToArray();foreach(var r in selected)Validate(r);
   // Contiguous runs preserve the teacher's global region order, including page 1 -> page 2 -> page 1.
   var runs=new List<List<QuestionRegion>>();foreach(var r in selected){if(runs.Count==0||runs[runs.Count-1][0].PageId!=r.PageId)runs.Add(new List<QuestionRegion>());runs[runs.Count-1].Add(r);}if(runs.Count>6)throw new InvalidOperationException("组合超过6张，请将同页区域排在一起，或分成不同题目。");
   var photos=new List<PhotoData>();int number=0;foreach(var run in runs){token.ThrowIfCancellationRequested();var page=Pages.Single(x=>x.Id==run[0].PageId);var source=page.Decode();int width=run.Max(r=>r.Bounds.Width),sourceHeight=run.Sum(r=>r.Bounds.Height);if((long)width*sourceHeight>30000000)throw new InvalidOperationException("组合图过长，请缩小选区或分成不同题目。");const int header=32,gap=8;double scale=1;int w=Math.Max(220,(int)Math.Ceiling(width*scale)),h=(int)Math.Ceiling(sourceHeight*scale+run.Count*(header+gap)+12);if((long)w*h>10000000)throw new InvalidOperationException("组合图解码内存过大，请减少区域。");var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawRectangle(Brushes.White,null,new Rect(0,0,w,h));double y=6;foreach(var r in run){token.ThrowIfCancellationRequested();var crop=new CroppedBitmap(source,r.Bounds);crop.Freeze();var label=new FormattedText("区域 "+(++number)+" · 第"+(Pages.IndexOf(page)+1)+"页",System.Globalization.CultureInfo.GetCultureInfo("zh-CN"),FlowDirection.LeftToRight,new Typeface("Microsoft YaHei"),20,Brushes.DimGray,1);dc.DrawText(label,new Point(6,y));y+=header;dc.DrawImage(crop,new Rect(0,y,r.Bounds.Width*scale,r.Bounds.Height*scale));y+=r.Bounds.Height*scale+gap;}}
    var bitmap=new RenderTargetBitmap(w,h,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);bitmap.Freeze();photos.Add(PhotoData.CreateComposed(bitmap,"组题 "+Active.Name+" · "+photos.Count,high));}
   token.ThrowIfCancellationRequested();if(disposed||stamp!=Revision||groupId!=ActiveId)throw new OperationCanceledException("题目或区域已变化，旧组合未使用。");if(photos.Sum(x=>(long)x.Jpeg.Length)>12L*1024*1024)throw new InvalidOperationException("本题组合图超过12MB，请减少无关内容。");return new QuestionPayload{GroupId=groupId,GroupName=Active.Name,RegionCount=selected.Length,SourcePageCount=selected.Select(r=>r.PageId).Distinct().Count(),Revision=stamp,Images=photos.ToArray(),Instruction="这些已选区域按编号共同组成同一道题。请合并全部区域后作答和追问，不把它们拆成独立题，不推断未选内容。若缺少共享题干或完整图形，先提示补选，不猜题。"};
  }
  internal async Task<QuestionPayload> ComposeAsync(bool high,CancellationToken token){long stamp=Revision;try{var result=await Task.Run(()=>Compose(high,token),token).ConfigureAwait(false);if(disposed||Revision!=stamp)throw new OperationCanceledException("题目已变化，旧组合未使用。");return result;}catch(Exception)when(disposed||Revision!=stamp){throw new OperationCanceledException("题目已变化，旧组合未使用。");}}
  internal static void Prune(string root){if(!Directory.Exists(root))return;string fullRoot=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;foreach(string candidate in Directory.GetDirectories(root,"regions_*")){try{var dir=new DirectoryInfo(candidate);Guid id;string full=Path.GetFullPath(candidate);if(!full.StartsWith(fullRoot,StringComparison.OrdinalIgnoreCase)||!Guid.TryParseExact(dir.Name.Substring(8),"N",out id)||(dir.Attributes&FileAttributes.ReparsePoint)!=0||dir.LastWriteTimeUtc>DateTime.UtcNow.AddDays(-1)||!File.Exists(Path.Combine(full,"owned.cache"))||File.ReadAllText(Path.Combine(full,"owned.cache"))!="QuestionWorkspace v1"||Directory.GetDirectories(full).Length>0)continue;var files=Directory.GetFiles(full);if(files.Any(f=>(File.GetAttributes(f)&FileAttributes.ReparsePoint)!=0||!System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileName(f),@"^(?:owned\.cache|[a-f0-9]{32}\.png(?:\.(?:new|analysis\.png|ocr\.json))?)$")))continue;foreach(string file in files)File.Delete(file);Directory.Delete(full,false);}catch(IOException){}catch(UnauthorizedAccessException){}}}
  public void Dispose(){if(disposed)return;disposed=true;Revision++;Regions.Clear();Groups.Clear();Pages.Clear();try{if(Directory.Exists(folder))Directory.Delete(folder,true);}catch(IOException){}catch(UnauthorizedAccessException){}}
 }
}
